def _traverse_options(cls, obj, opt_type, opts, specs=None, keyfn=None, defaults=True):
    # Initialize an empty dictionary to store the options
    options = {}

    # Traverse the object
    for key, value in obj.items():
        # Check if the key is of the specified type and option
        if key in opts:
            # If a key function is provided, use it to group the options
            if keyfn:
                key = keyfn(key)
            # Add the option to the dictionary
            options[key] = value

    # If defaults are enabled, add the defaults to the options
    if defaults:
        for key, value in cls.defaults.items():
            if key in opts:
                if keyfn:
                    key = keyfn(key)
                options[key] = value

    return options

