def elog(exc, func, args=None, kwargs=None, str=str, pretty=True, name=''):
    """For logging exception-raising function invocations during randomized unit tests."""
    try:
        if args is None:
            args = ()
        if kwargs is None:
            kwargs = {}
        result = func(*args, **kwargs)
        if isinstance(result, exc):
            logging.error(f"Function {name} raised {exc.__name__} as expected")
        else:
            logging.error(f"Function {name} did not raise {exc.__name__} as expected")
    except Exception as e:
        if isinstance(e, exc):
            logging.error(f"Function {name} raised {exc.__name__} as expected")
        else:
            logging.error(f"Function {name} raised unexpected exception: {str(e)}")
            if pretty:
                traceback.print_exc()

