import numpy as np

def distance_measure_common(A, func, alpha, R, k, epsilon):
    """Create strength of connection matrix from a function applied to relaxation vectors."""
    # Apply the function to the relaxation vectors
    result = func(A, alpha, R, k, epsilon)

    # Create the strength of connection matrix
    strength_matrix = np.zeros((len(result), len(result)))

    for i in range(len(result)):
        for j in range(len(result)):
            if i != j:
                strength_matrix[i][j] = np.exp(-epsilon * np.linalg.norm(result[i] - result[j]))

    return strength_matrix

