import time

def send_until(self, send, regexps, not_there=False, echo=False, note=False, debug_command=None):
    timeout = time.time() + 60   # 60 seconds from now
    while True:
        output = self.send(send, echo=echo, note=note)
        for regexp in regexps:
            if not_there and re.search(regexp, output):
                if debug_command:
                    self.send(debug_command)
                time.sleep(1)  # wait for 1 second before next attempt
                continue
            elif not not_there and not re.search(regexp, output):
                if debug_command:
                    self.send(debug_command)
                time.sleep(1)  # wait for 1 second before next attempt
                continue
            else:
                return
        if time.time() > timeout:
            raise Exception("Timeout")

