import numpy as np

def sersic(x, y, n_sersic, R_sersic, k_eff, e1, e2, center_x=0, center_y=0):
    """Sersic function"""
    rho = np.sqrt((x - center_x)**2 + (y - center_y)**2)
    return k_eff * np.exp(-k_eff * (rho**(1/n_sersic) - 1))

def derivatives(x, y, n_sersic, R_sersic, k_eff, e1, e2, center_x=0, center_y=0):
    """returns df/dx and df/dy of the Sersic function"""
    rho = np.sqrt((x - center_x)**2 + (y - center_y)**2)
    if rho == 0:
        return 0, 0
    else:
        df_dx = -k_eff * (x - center_x) * np.exp(-k_eff * (rho**(1/n_sersic) - 1)) / rho
        df_dy = -k_eff * (y - center_y) * np.exp(-k_eff * (rho**(1/n_sersic) - 1)) / rho
        return df_dx, df_dy

