def match_gpus(available_devices, requirements):
    available_devices.sort(key=lambda x: x.memory)
    requirements.sort(key=lambda x: x.memory, reverse=True)

    matched_devices = []
    for req in requirements:
        for dev in available_devices:
            if dev.memory >= req.memory:
                matched_devices.append(dev)
                available_devices.remove(dev)
