def integral(A=None, dF=None, F=None, axis=0, trapez=False, cumulative=False):
    if A is None:
        A = np.ones(len(dF)+1)
    if dF is None:
        dF = np.ones(len(A)-1)
    if F is None:
        F = np.cumsum(dF)

    if trapez:
        integral_values = np.cumsum((A[:-1] + A[1:]) * dF / 2)
    else:
        integral_values = np.cumsum(A[:-1] * dF)

    if cumulative:
        integral_values = np.insert(integral_values, 0, 0)

    return integral_values
